"use client";

import { useEffect, useMemo, useState } from "react";
import { Field, fieldAria, selectClass } from "@/components/common/form-parts";
import { Combobox, type ComboOption } from "@/components/forms/combobox";
import { INDIAN_STATES } from "@/lib/constants";
import { useT } from "@/i18n/client";
import { cn } from "@/lib/utils";

/** Generated by scripts/build-location-data.mjs from the India Post directory. */
interface StateLocations {
  state: string;
  districts: Array<{ name: string; places: Array<[name: string, pin: string]> }>;
}

const cache = new Map<string, Promise<unknown>>();
const slug = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");

function loadJson<T>(path: string): Promise<T | null> {
  if (!cache.has(path)) {
    cache.set(
      path,
      fetch(path)
        .then((r) => (r.ok ? r.json() : null))
        .catch(() => {
          cache.delete(path); // allow a retry when back online
          return null;
        }),
    );
  }
  return cache.get(path) as Promise<T | null>;
}

/** Loads a JSON file once per page; `null` path means nothing to load. */
function useJson<T>(path: string | null) {
  const [loaded, setLoaded] = useState<{ path: string; data: T | null } | null>(null);
  useEffect(() => {
    if (!path) return;
    let live = true;
    loadJson<T>(path).then((data) => {
      if (live) setLoaded({ path, data });
    });
    return () => {
      live = false;
    };
  }, [path]);
  const current = path && loaded?.path === path ? loaded : null;
  return { data: current?.data ?? null, loading: Boolean(path) && !current };
}

export interface LocationPickerValues {
  /** Omit when the form has no state field (the state is then only used to find towns). */
  state?: string;
  district: string;
  /** Omit for district-only filters. */
  city?: string;
  /** When present and empty, choosing a town fills in its PIN code. */
  pincode?: string;
}
type PickerField = keyof LocationPickerValues;

/**
 * State → District → City/Town, each searchable, from the India Post directory.
 * Districts can also be searched across India before a state is chosen;
 * picking one fills in its state. Anything missing can still be typed in.
 */
export function LocationPickers({
  values,
  onChange,
  errors = {},
  required,
  idPrefix = "",
  labels = {},
  emptyStateLabel = "Select…",
  className,
}: {
  values: LocationPickerValues;
  onChange: (field: PickerField, value: string) => void;
  errors?: Partial<Record<PickerField, string | undefined>>;
  /** `true` marks every shown field as required. */
  required?: boolean | Partial<Record<"state" | "district" | "city", boolean>>;
  /** Keeps ids unique when a page shows several pickers. */
  idPrefix?: string;
  labels?: Partial<Record<"state" | "district" | "city", string>>;
  /** First option of the state list, e.g. "Any" in search filters. */
  emptyStateLabel?: string;
  className?: string;
}) {
  const t = useT();
  const showState = values.state !== undefined;
  const showCity = values.city !== undefined;
  const isRequired = (f: "state" | "district" | "city") => (typeof required === "boolean" ? required : Boolean(required?.[f]));
  const id = (f: string) => `${idPrefix}${f}`;

  // The state whose towns we need. Without a state field, remember the state of
  // the district picked from the all-India list (or look it up for saved values).
  const [pickedState, setPickedState] = useState<string | null>(null);
  const { data: allDistricts } = useJson<Array<[string, string]>>(
    !showState || !values.state ? "/data/locations/districts.json" : null,
  );
  const inferredState = useMemo(() => {
    if (showState) return values.state || "";
    if (pickedState) return pickedState;
    return allDistricts?.find(([name]) => name === values.district)?.[1] ?? "";
  }, [showState, values.state, values.district, pickedState, allDistricts]);

  const { data: stateData, loading: stateLoading } = useJson<StateLocations>(inferredState ? `/data/locations/${slug(inferredState)}.json` : null);

  const districtOptions = useMemo<ComboOption[]>(() => {
    // With a chosen state, offer that state's districts; otherwise search all of India.
    if (showState && values.state) return stateData?.districts.map((d) => ({ value: d.name })) ?? [];
    return allDistricts?.map(([name, state]) => ({ value: name, hint: t(state), data: state })) ?? [];
  }, [showState, values.state, stateData, allDistricts, t]);

  const placeOptions = useMemo<ComboOption[]>(() => {
    const district = stateData?.districts.find((d) => d.name === values.district);
    return district?.places.map(([value, pin]) => ({ value, hint: pin, data: pin })) ?? [];
  }, [stateData, values.district]);

  const districtLoading = showState && values.state ? stateLoading : !allDistricts;

  const district = (
    <Field id={id("district")} label={labels.district ?? "District"} required={isRequired("district")} error={errors.district}>
      <Combobox
        id={id("district")}
        value={values.district}
        options={districtOptions}
        loading={districtLoading}
        placeholder="Search district"
        invalid={Boolean(errors.district)}
        describedBy={errors.district ? `${id("district")}-error` : undefined}
        emptyText="Not listed? Type the name"
        onChange={(v, option) => {
          if (v !== values.district && showCity) onChange("city", "");
          onChange("district", v);
          const optionState = option?.data;
          if (optionState) {
            setPickedState(optionState);
            if (showState && values.state !== optionState) onChange("state", optionState);
          } else if (!showState) {
            setPickedState(null);
          }
        }}
      />
    </Field>
  );

  const city = showCity ? (
    <Field id={id("city")} label={labels.city ?? "City / town / village"} required={isRequired("city")} error={errors.city}>
      <Combobox
        id={id("city")}
        value={values.city ?? ""}
        options={placeOptions}
        loading={Boolean(values.district) && stateLoading}
        disabled={!values.district}
        placeholder={values.district ? "Search city, town or village" : "Choose a district first"}
        invalid={Boolean(errors.city)}
        describedBy={errors.city ? `${id("city")}-error` : undefined}
        emptyText="Not listed? Type the name"
        onChange={(v, option) => {
          onChange("city", v);
          // Fill the PIN from the post office, without overwriting one already typed.
          if (option?.data && values.pincode === "") onChange("pincode", option.data);
        }}
      />
    </Field>
  ) : null;

  return (
    <div className={cn("space-y-4", className)}>
      {showState ? (
        <Field id={id("state")} label={labels.state ?? "State / union territory"} required={isRequired("state")} error={errors.state}>
          <select
            {...fieldAria(id("state"), errors.state)}
            className={selectClass}
            autoComplete="address-level1"
            value={values.state}
            onChange={(e) => {
              onChange("state", e.target.value);
              onChange("district", "");
              if (showCity) onChange("city", "");
              setPickedState(null);
            }}
          >
            <option value="">{t(emptyStateLabel)}</option>
            {INDIAN_STATES.map((s) => (
              <option key={s} value={s}>
                {t(s)}
              </option>
            ))}
          </select>
        </Field>
      ) : null}
      {city ? (
        <div className="grid gap-4 sm:grid-cols-2">
          {district}
          {city}
        </div>
      ) : (
        district
      )}
    </div>
  );
}

/**
 * The same pickers for plain forms (server actions, GET filters): keeps its own
 * state and submits the values as hidden inputs under the given names.
 */
export function LocationFields({
  names,
  defaults = {},
  ...props
}: {
  names: Partial<Record<PickerField, string>> & { district: string };
  defaults?: Partial<LocationPickerValues>;
} & Omit<React.ComponentProps<typeof LocationPickers>, "values" | "onChange">) {
  const [values, setValues] = useState<LocationPickerValues>(() => ({
    district: defaults.district ?? "",
    ...(names.state ? { state: defaults.state ?? "" } : {}),
    ...(names.city ? { city: defaults.city ?? "" } : {}),
    ...(names.pincode ? { pincode: defaults.pincode ?? "" } : {}),
  }));
  return (
    <>
      <LocationPickers {...props} values={values} onChange={(field, value) => setValues((prev) => ({ ...prev, [field]: value }))} />
      {(Object.keys(names) as PickerField[]).map((field) => (
        <input key={field} type="hidden" name={names[field]} value={values[field] ?? ""} />
      ))}
    </>
  );
}
